import {AdvertisingPlatform,AD_PLACEMENTS} from './advertising-platform.mjs';
import {shopOffers,shopToday} from './shop-state.mjs';
import {commitShopReward} from './shop-rewards.mjs';
import {loadSolo} from './campaign-profile.mjs';
import {itemInfo} from './campaign-growth-data.mjs';
import {sheetStyle} from './campaign-system-ui.mjs';
import {installOnboarding} from './onboarding-guide.mjs';
import './platform.mjs';
const ads=new AdvertisingPlatform(globalThis.arcaneMobile?.ads||globalThis.arcaneAds||null),root=document.getElementById('shop-rewards'),status=document.getElementById('shop-status');let available=false,busy=false,testMode=false;
function offerButton(o,today){if((today.counts[o.id]||0)>=o.limit)return '今日已领完';if(!available)return '广告补给 · 暂未开放';if(o.adsRequired===2)return today.ticketAds?'再看1次 · 领取抽奖券':'观看第1次广告';return '观看广告 · 领取';}
function render(){const profile=loadSolo(localStorage),today=shopToday(profile);document.getElementById('shop-coins').textContent=profile.coins;root.innerHTML=shopOffers(profile).map(o=>`<article class="shop-offer"><i class="shop-item" aria-hidden="true" style="${sheetStyle('items',itemInfo({type:o.icon}).icon)}"></i><h3>${o.name}</h3><p>${o.copy}</p><small>今日 ${today.counts[o.id]||0} / ${o.limit}${o.adsRequired===2?' · 广告进度 '+(today.ticketAds||0)+' / 2':''}</small><button data-offer="${o.id}" ${busy||(today.counts[o.id]||0)>=o.limit?'disabled':''}>${offerButton(o,today)}</button></article>`).join('');}
root.addEventListener('click',async e=>{const b=e.target.closest('[data-offer]');if(!b||busy)return;if(!available){status.textContent='广告补给暂未开放，正常探索与通关奖励照常获得。';return;}if(!document.getElementById('shop-privacy').checked){status.textContent='请先阅读并确认隐私与广告说明。';return;}busy=true;render();try{const result=await ads.showRewarded(b.dataset.offer==='ticket'?AD_PLACEMENTS.ticket:b.dataset.offer==='coins'?AD_PLACEMENTS.coins:AD_PLACEMENTS.item,{privacyAccepted:true});if(!result.completed){const failed=['loadFailed','loadTimeout','showFailed','showTimeout','videoFailed','notAvailable'].includes(result.reason);status.textContent=failed?`广告暂时加载失败${Number.isInteger(result.errorCode)?'（'+result.errorCode+'）':''}，请稍后再试，未扣领取次数。`:'本次未完成广告，奖励和领取次数均未改变。';return;}const next=commitShopReward(localStorage,b.dataset.offer,result);status.textContent=b.dataset.offer==='ticket'?(next.shop.ticketAds?'已保存第1次广告进度，再看1次即可获得1张抽奖券。':'获得1张抽奖券，已直接到账；每日任务同步计为领取。'):'馈赠已保存：金币已到账，道具可在背包查看，每日任务同步计为领取。';}catch(error){status.textContent=error.message;}finally{busy=false;render();}});
render();ads.status().then(s=>{available=s.configured&&s.rewarded;testMode=s.testMode===true;status.textContent=available?(testMode?'广告联调测试中：自愿观看测试广告验证奖励，尚未开放正式变现。':'选择需要的补给，自愿观看后领取。'):'广告补给暂未开放，正常探索与通关奖励照常获得。';render();}).catch(()=>{status.textContent='暂时没有可观看的广告，请稍后再来。';});
installOnboarding('shop');
